package com.wifitrack;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import android.webkit.*;import android.net.*;import android.net.http.SslError;import java.net.*;import java.util.*;
public final class MainActivity extends Activity {
 private TextView status;private final Handler handler=new Handler(Looper.getMainLooper());private WebView router;
 private final Runnable update=new Runnable(){public void run(){if(status!=null){status.setText(getSharedPreferences("recorder",MODE_PRIVATE).getString("status","Recorder has not started")+"\n\nLaptop dashboard (same Wi-Fi):\n"+addresses());handler.postDelayed(this,3000);}}};
 @Override public void onCreate(Bundle b){super.onCreate(b);RouterTrust.load(this);home();}
 private void home(){handler.removeCallbacks(update);if(router!=null){router.destroy();router=null;}LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(30,30,30,30);TextView heading=new TextView(this);heading.setText("Wi-Fi Data Track\nRedmi recorder + laptop dashboard");heading.setTextSize(23);root.addView(heading);
  TextView note=new TextView(this);note.setText("Total WAN1 usage only. Daily records start after the first baseline. Phone must stay on and connected. Dashboard uses HTTP on trusted home Wi-Fi; do not reuse your router password.");root.addView(note);status=new TextView(this);root.addView(status);
  button(root,"1. Set dashboard password",()->password());button(root,"Import router certificate (if needed)",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,41);});button(root,"2. Router login (inside app)",()->login());button(root,"3. Start recorder + dashboard",()->{if(!new DashboardAuth(this).configured()){password();return;}startForegroundService(new Intent(this,RecorderService.class));});button(root,"Stop recorder + dashboard",()->stopService(new Intent(this,RecorderService.class)));button(root,"Battery settings",()->startActivity(new Intent(android.provider.Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS)));
  ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);handler.post(update);
 }
 private void button(LinearLayout l,String label,Runnable action){Button b=new Button(this);b.setText(label);b.setOnClickListener(v->action.run());l.addView(b);}
 private void password(){EditText input=new EditText(this);input.setInputType(129);input.setHint("12–128 characters; separate from router password");new AlertDialog.Builder(this).setTitle("Dashboard password").setView(input).setMessage("Used from your laptop. Changing it stops the server and invalidates active sessions; tap Start again.").setPositiveButton("Save",(d,w)->{try{new DashboardAuth(this).setPassword(input.getText().toString());stopService(new Intent(this,RecorderService.class));Toast.makeText(this,"Saved. Start the recorder again.",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}).setNegativeButton("Cancel",null).show();}
 private void login(){handler.removeCallbacks(update);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);button(box,"Done — return to recorder",()->{CookieManager.getInstance().flush();home();});router=new WebView(this);router.getSettings().setJavaScriptEnabled(true);router.getSettings().setDomStorageEnabled(true);router.getSettings().setAllowFileAccess(false);router.getSettings().setAllowContentAccess(false);CookieManager.getInstance().setAcceptCookie(true);router.setWebViewClient(new WebViewClient(){
   @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest req){Uri u=req.getUrl();return !"https".equals(u.getScheme())||!"192.168.1.1".equals(u.getHost())||(u.getPort()!=-1&&u.getPort()!=443);}
   @Override public void onReceivedSslError(WebView v,SslErrorHandler h,SslError error){try {Uri u=Uri.parse(error.getUrl());byte[] der=android.net.http.SslCertificate.saveState(error.getCertificate()).getByteArray("x509-certificate");if("https".equals(u.getScheme())&&"192.168.1.1".equals(u.getHost())&&(u.getPort()==-1||u.getPort()==443)&&RouterTrust.matches(der)){h.proceed();return;}}catch(Exception ignored){}h.cancel();new AlertDialog.Builder(MainActivity.this).setTitle("Router certificate needs setup").setMessage("Import and verify the exact router certificate using the home screen. This app accepts only that pinned certificate for 192.168.1.1; changed certificates are rejected. Chrome trust is separate.").setPositiveButton("OK",null).show();}
  });box.addView(router,new LinearLayout.LayoutParams(-1,0,1));setContentView(box);router.loadUrl(RouterClient.BASE+"/web_whw/");}
 private String addresses(){StringBuilder s=new StringBuilder();try{for(NetworkInterface ni:Collections.list(NetworkInterface.getNetworkInterfaces())){if(!ni.isUp()||ni.isLoopback())continue;for(InetAddress a:Collections.list(ni.getInetAddresses()))if(a instanceof Inet4Address&&a.isSiteLocalAddress())s.append("http://").append(a.getHostAddress()).append(":8080\n");}}catch(Exception e){return "Connect phone to Airtel Wi-Fi";}return s.length()>0?s.toString():"Connect phone to Airtel Wi-Fi";}
 @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code!=41||result!=RESULT_OK||data==null||data.getData()==null)return;try(java.io.InputStream in=getContentResolver().openInputStream(data.getData())){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>65536)throw new Exception("Certificate file is too large");}java.security.cert.X509Certificate cert=(java.security.cert.X509Certificate)java.security.cert.CertificateFactory.getInstance("X.509").generateCertificate(new java.io.ByteArrayInputStream(out.toByteArray()));String fp=RouterTrust.fingerprint(cert);new AlertDialog.Builder(this).setTitle("Verify router certificate").setMessage("Compare this SHA-256 fingerprint with the certificate shown for your router in Chrome. Trust only if they match. This pin explicitly accepts this certificate for 192.168.1.1, including self-signed or expired certificates.\n\n"+fp).setPositiveButton("Fingerprint matches — trust",(d,w)->{try{stopService(new Intent(this,RecorderService.class));RouterTrust.save(this,cert);Toast.makeText(this,"Router certificate pinned. Log in, then Start.",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"Could not save certificate",Toast.LENGTH_LONG).show();}}).setNegativeButton("Cancel",null).show();}catch(Exception e){Toast.makeText(this,"Import failed: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
 @Override protected void onDestroy(){handler.removeCallbacks(update);if(router!=null)router.destroy();super.onDestroy();}
 @Override public void onBackPressed(){if(router!=null)home();else super.onBackPressed();}
}
